"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["29623"],{19052(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.quadro_modalidade_nao_selecionada","status":422,"titulo":"O quadro traz uma modalidade que n\xe3o est\xe1 selecionada nesta oferta"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.quadro_modalidade_nao_selecionada","requisitos":[],"oQueAconteceu":["Uma das entradas do bloco `quadro` do corpo do pedido traz um `ModalidadeId` que\\nn\xe3o est\xe1 entre os `modalidadeIds` selecionados na mesma distribui\xe7\xe3o. O\\n`quadro` s\xf3 declara quantidade para modalidades que a oferta de fato\\nseleciona \u2014 uma entrada \xf3rf\xe3, sem modalidade correspondente, n\xe3o tem o que\\ndescrever.","Esta \xe9 uma reconcilia\xe7\xe3o de **Ids brutos do corpo do pedido**, sem consultar\\nnenhum cadastro \u2014 roda antes de qualquer resolu\xe7\xe3o contra o cat\xe1logo de\\nmodalidades, logo depois de resolver a regra de ajuste (quando informada).\\nN\xe3o acumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira entrada \xf3rf\xe3 que\\ninterrompe o processamento da distribui\xe7\xe3o."],"comoResolver":["Remova do `quadro` qualquer entrada cujo `ModalidadeId` n\xe3o esteja em\\n`modalidadeIds`, ou inclua a modalidade correspondente em `modalidadeIds`\\nse a inten\xe7\xe3o era selecion\xe1-la."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);